import 'dart:async';
import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:shared_preferences/shared_preferences.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();

  // Memaksa mesin Flutter memuat font secara dinamis di runtime (bypass bug Web)
  try {
    final fontLoader = FontLoader('DMSerifDisplay');
    fontLoader.addFont(rootBundle.load('assets/fonts/dm_serif_display_regular.ttf'));
    await fontLoader.load();
    debugPrint('BERHASIL: Font DM Serif Display berhasil dimuat secara manual!');
  } catch (e) {
    debugPrint('\n=========== ERROR FONT ===========');
    debugPrint('Gagal memuat font: $e');
    debugPrint('Pastikan file dm_serif_display_regular.ttf benar-benar ada di folder assets/fonts/');
    debugPrint('==================================\n');
  }

  SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);
  SystemChrome.setSystemUIOverlayStyle(
    const SystemUiOverlayStyle(
      statusBarColor: Colors.transparent,
      systemNavigationBarColor: Colors.transparent,
      systemNavigationBarContrastEnforced: false,
    ),
  );
  runApp(const WorkoutRumahApp());
}

class ExerciseData {
  const ExerciseData({
    required this.name,
    required this.subtitle,
    required this.sets,
    required this.reps,
    required this.restSeconds,
    this.durationSeconds,
    required this.color,
    required this.icon,
  });

  final String name;
  final String subtitle;
  final int sets;
  final int reps;
  final int restSeconds;
  final int? durationSeconds;
  final Color color;
  final IconData icon;
}

class WorkoutHistory {
  const WorkoutHistory({
    required this.title,
    required this.completedAt,
    required this.durationMinutes,
    required this.exerciseCount,
    required this.calories,
  });

  final String title;
  final DateTime completedAt;
  final int durationMinutes;
  final int exerciseCount;
  final int calories;

  Map<String, dynamic> toJson() => {
        'title': title,
        'completedAt': completedAt.toIso8601String(),
        'durationMinutes': durationMinutes,
        'exerciseCount': exerciseCount,
        'calories': calories,
      };

  factory WorkoutHistory.fromJson(Map<String, dynamic> json) {
    return WorkoutHistory(
      title: json['title'] as String? ?? 'Workout',
      completedAt: DateTime.tryParse(json['completedAt'] as String? ?? '') ??
          DateTime.now(),
      durationMinutes: json['durationMinutes'] as int? ?? 0,
      exerciseCount: json['exerciseCount'] as int? ?? 0,
      calories: json['calories'] as int? ?? 0,
    );
  }
}

class UserProfile {
  const UserProfile({
    required this.name,
    required this.email,
  });

  final String name;
  final String email;

  UserProfile copyWith({String? name, String? email}) => UserProfile(
        name: name ?? this.name,
        email: email ?? this.email,
      );

  Map<String, dynamic> toJson() => {
        'name': name,
        'email': email,
      };

  factory UserProfile.fromJson(Map<String, dynamic> json) => UserProfile(
        name: json['name'] as String? ?? 'Andi Ramadhan',
        email: json['email'] as String? ?? 'andi@example.com',
      );
}

class ScheduleItem {
  const ScheduleItem({
    required this.id,
    required this.day,
    required this.time,
    required this.workout,
    required this.active,
    this.reminderEnabled = true,
    this.reminderMinutes = 30,
  });

  final String id;
  final String day;
  final String time;
  final String workout;
  final bool active;
  final bool reminderEnabled;
  final int reminderMinutes;

  ScheduleItem copyWith({
    bool? active,
    bool? reminderEnabled,
    int? reminderMinutes,
  }) =>
      ScheduleItem(
        id: id,
        day: day,
        time: time,
        workout: workout,
        active: active ?? this.active,
        reminderEnabled: reminderEnabled ?? this.reminderEnabled,
        reminderMinutes: reminderMinutes ?? this.reminderMinutes,
      );

  Map<String, dynamic> toJson() => {
        'id': id,
        'day': day,
        'time': time,
        'workout': workout,
        'active': active,
        'reminderEnabled': reminderEnabled,
        'reminderMinutes': reminderMinutes,
      };

  factory ScheduleItem.fromJson(Map<String, dynamic> json) => ScheduleItem(
        id: json['id'] as String? ?? DateTime.now().toIso8601String(),
        day: json['day'] as String? ?? 'Senin',
        time: json['time'] as String? ?? '18:30',
        workout: json['workout'] as String? ?? 'Full Body',
        active: json['active'] as bool? ?? true,
        reminderEnabled: json['reminderEnabled'] as bool? ?? true,
        reminderMinutes: json['reminderMinutes'] as int? ?? 30,
      );
}

