class WorkoutAppState extends ChangeNotifier {
WorkoutAppState() {
_load();
}

ThemeMode themeMode = ThemeMode.system;
int accentIndex = 0;
bool isLoading = true;
UserProfile profile = const UserProfile(
name: 'Andi Ramadhan',
email: 'andi@example.com',
);
List<WorkoutHistory> history = [];
List<ScheduleItem> schedules = [
const ScheduleItem(
id: 'default-1',
day: 'Senin',
time: '18:30',
workout: 'Full Body',
active: true,
reminderEnabled: true,
reminderMinutes: 30,
),
const ScheduleItem(
id: 'default-2',
day: 'Rabu',
time: '18:30',
workout: 'Full Body',
active: true,
reminderEnabled: true,
reminderMinutes: 30,
),
const ScheduleItem(
